import React,{useState} from "react";import {addDoc,collection,serverTimestamp} from "firebase/firestore";import {db} from "../firebase";
export default function Contact(){const init={name:"",email:"",phone:"",message:""};const [f,setF]=useState(init),[s,setS]=useState("");const submit=async e=>{e.preventDefault();setS("saving");try{await addDoc(collection(db,"contactMessages"),{...f,createdAt:serverTimestamp(),status:"new"});setF(init);setS("done")}catch(err){console.error(err);setS("error")}};return <div className="grid gap-8 md:grid-cols-2"><section><p className="text-sm font-semibold text-sky-700">Contact</p><h1 className="mt-2 text-3xl font-bold text-slate-900">Get in Touch</h1><p className="mt-3 text-slate-600">Questions about programs, availability, enrollment, or overnight-care plans? We’re happy to help.</p><div className="mt-6 space-y-3 text-slate-700"><p><strong>Phone:</strong> (432) 215-8560</p><p><strong>Email:</strong> info@elsieschildcarecenter.com</p><p><strong>Location:</strong> Midland, Texas</p><p><strong>Day program:</strong> Monday–Friday, 6:00 AM–6:00 PM</p></div></section><form onSubmit={submit} className="space-y-4 rounded-2xl bg-white p-6 ring-1 ring-slate-200">{[["name","Full Name","text"],["email","Email","email"],["phone","Phone","tel"]].map(([n,l,t])=><label key={n} className="block text-sm font-medium">{l}<input type={t} value={f[n]} onChange={e=>setF({...f,[n]:e.target.value})} className="mt-1 w-full rounded-xl border p-3" required/></label>)}<label className="block text-sm font-medium">Message<textarea rows="5" value={f.message} onChange={e=>setF({...f,message:e.target.value})} className="mt-1 w-full rounded-xl border p-3" required/></label><button className="w-full rounded-xl bg-sky-700 py-3 font-semibold text-white">{s==="saving"?"Sending…":"Send Message"}</button>{s==="done"&&<p className="text-sm text-green-700">Message sent successfully.</p>}{s==="error"&&<p className="text-sm text-red-700">Unable to send. Please try again.</p>}</form></div>}
