import React from "react";
import { Link } from "react-router-dom";
import { useAuth } from "../context/AuthContext";
export default function ParentPortal(){const {user,profile,logout}=useAuth();return <div className="space-y-6"><div className="rounded-3xl bg-gradient-to-br from-sky-700 to-indigo-700 p-8 text-white"><p className="text-sm text-white/80">Parent Portal</p><h1 className="mt-2 text-3xl font-bold text-white">Welcome, {profile?.name || user?.email}</h1><p className="mt-2 text-white/85">Your family dashboard is ready for enrollment updates, center resources, and future attendance features.</p></div><div className="grid gap-4 md:grid-cols-3"><Card title="Enrollment" text="Submit or update an enrollment request." to="/enroll"/><Card title="Parent Handbook" text="Review center policies and family resources." to="/handbook"/><Card title="Schedule a Tour" text="Request a visit to the center." to="/schedule-tour"/></div><div className="rounded-2xl bg-white p-6 ring-1 ring-slate-200"><h2 className="text-xl font-bold text-slate-900">Account</h2><p className="mt-2 text-sm text-slate-600">Signed in as {user?.email}</p><button onClick={logout} className="mt-4 rounded-xl bg-slate-900 px-4 py-2 text-sm font-semibold text-white">Sign Out</button></div></div>}
function Card({title,text,to}){return <Link to={to} className="rounded-2xl bg-white p-6 shadow-sm ring-1 ring-slate-200 hover:shadow-md"><h2 className="text-lg font-bold text-slate-900">{title}</h2><p className="mt-2 text-sm text-slate-600">{text}</p><span className="mt-4 inline-block text-sm font-semibold text-sky-700">Open →</span></Link>}
