import React,{useState} from "react";import {addDoc,collection,serverTimestamp} from "firebase/firestore";import {db} from "../firebase";
export default function ScheduleTour(){const init={name:"",email:"",phone:"",preferredDate:"",message:""};const [f,setF]=useState(init),[s,setS]=useState("");const submit=async e=>{e.preventDefault();setS("saving");try{await addDoc(collection(db,"tourRequests"),{...f,createdAt:serverTimestamp(),status:"new"});setF(init);setS("done")}catch(err){console.error(err);setS("error")}};return <div className="space-y-7"><header><h1 className="text-3xl font-bold text-slate-900">Schedule a Tour</h1><p className="mt-2 text-slate-600">Visit our center, meet our team, and learn about our programs.</p></header><form onSubmit={submit} className="grid gap-4 rounded-2xl bg-white p-6 ring-1 ring-slate-200 md:grid-cols-2">{[["name","Your Name","text"],["email","Email","email"],["phone","Phone","tel"],["preferredDate","Preferred Date","date"]].map(([n,l,t])=><label key={n} className="text-sm font-semibold text-slate-700">{l}<input type={t} value={f[n]} onChange={e=>setF({...f,[n]:e.target.value})} className="mt-1 w-full rounded-xl border p-3" required/></label>)}<label className="text-sm font-semibold text-slate-700 md:col-span-2">Message (optional)<textarea rows="4" value={f.message} onChange={e=>setF({...f,message:e.target.value})} className="mt-1 w-full rounded-xl border p-3"/></label><button disabled={s==="saving"} className="rounded-xl bg-sky-700 px-5 py-3 font-semibold text-white md:col-span-2">{s==="saving"?"Submitting…":"Request Tour"}</button>{s==="done"&&<p className="text-green-700 md:col-span-2">Your tour request was submitted.</p>}{s==="error"&&<p className="text-red-700 md:col-span-2">Unable to submit. Please try again.</p>}</form></div>}
