import React, { useEffect, useState } from "react";
import { collection, getDocs, limit, orderBy, query } from "firebase/firestore";
import { db } from "../firebase";
import { useAuth } from "../context/AuthContext";
export default function AdminDashboard(){const {profile,logout}=useAuth();const [data,setData]=useState({enrollments:[],tours:[],contacts:[]});const [error,setError]=useState("");useEffect(()=>{(async()=>{try{const load=async(name)=>{const s=await getDocs(query(collection(db,name),orderBy("createdAt","desc"),limit(20)));return s.docs.map(d=>({id:d.id,...d.data()}))};const [enrollments,tours,contacts]=await Promise.all([load("enrollments"),load("tourRequests"),load("contactMessages")]);setData({enrollments,tours,contacts})}catch(e){setError("Could not load dashboard records. Check Firestore rules and indexes.");console.error(e)}})()},[]);return <div className="space-y-6"><div className="flex flex-col gap-3 rounded-3xl bg-slate-900 p-7 text-white md:flex-row md:items-center md:justify-between"><div><p className="text-sm text-white/70">Administration</p><h1 className="text-3xl font-bold text-white">Elsie’s Admin Dashboard</h1><p className="mt-1 text-sm text-white/70">Signed in as {profile?.name || "Administrator"}</p></div><button onClick={logout} className="rounded-xl bg-white px-4 py-2 text-sm font-semibold text-slate-900">Sign Out</button></div>{error&&<p className="rounded-xl bg-red-50 p-4 text-red-700">{error}</p>}<div className="grid gap-4 sm:grid-cols-3"><Stat n={data.enrollments.length} label="Recent enrollments"/><Stat n={data.tours.length} label="Recent tour requests"/><Stat n={data.contacts.length} label="Recent messages"/></div><Records title="Enrollment Requests" rows={data.enrollments} fields={["parentName","childName","program","phone"]}/><Records title="Tour Requests" rows={data.tours} fields={["name","preferredDate","email","phone"]}/><Records title="Contact Messages" rows={data.contacts} fields={["name","email","phone","message"]}/></div>}
function Stat({n,label}){return <div className="rounded-2xl bg-white p-6 ring-1 ring-slate-200"><div className="text-3xl font-bold text-sky-700">{n}</div><div className="text-sm text-slate-600">{label}</div></div>}
function Records({title,rows,fields}){return <section className="rounded-2xl bg-white p-6 ring-1 ring-slate-200"><h2 className="text-xl font-bold text-slate-900">{title}</h2>{rows.length===0?<p className="mt-3 text-sm text-slate-500">No records yet.</p>:<div className="mt-4 overflow-x-auto"><table className="min-w-full text-left text-sm"><thead><tr>{fields.map(f=><th key={f} className="border-b p-2 capitalize">{f}</th>)}</tr></thead><tbody>{rows.map(r=><tr key={r.id}>{fields.map(f=><td key={f} className="border-b p-2 align-top">{String(r[f]??"")}</td>)}</tr>)}</tbody></table></div>}</section>}
