import React, { useState } from "react";
import { addDoc, collection, serverTimestamp } from "firebase/firestore";
import { db } from "../../firebase";
export default function EnrollmentForm(){const initial={parentName:"",email:"",childName:"",age:"",phone:"",program:""};const [form,setForm]=useState(initial);const [status,setStatus]=useState("");const submit=async(e)=>{e.preventDefault();setStatus("saving");try{await addDoc(collection(db,"enrollments"),{...form,createdAt:serverTimestamp(),status:"new"});setForm(initial);setStatus("done")}catch(e){console.error(e);setStatus("error")}};return <div className="rounded-2xl bg-white p-6 shadow-sm ring-1 ring-slate-200"><h2 className="text-xl font-semibold text-sky-900">Enrollment Interest Form</h2><p className="mt-2 text-sm text-slate-600">Send your family’s information and we’ll follow up about availability and next steps.</p><form onSubmit={submit} className="mt-5 grid gap-4 md:grid-cols-2">{[["parentName","Parent/Guardian Name","text"],["email","Email","email"],["childName","Child’s Name","text"],["age","Child’s Age","number"],["phone","Phone Number","tel"]].map(([n,l,t])=><label key={n} className="text-sm font-medium text-slate-700">{l}<input name={n} type={t} value={form[n]} onChange={e=>setForm({...form,[n]:e.target.value})} className="mt-1 w-full rounded-xl border border-slate-300 px-3 py-2" required/></label>)}<label className="text-sm font-medium text-slate-700 md:col-span-2">Program<select name="program" value={form.program} onChange={e=>setForm({...form,program:e.target.value})} className="mt-1 w-full rounded-xl border border-slate-300 px-3 py-2" required><option value="">Select a program</option><option>Infant (6–17 months)</option><option>Toddler (18–35 months)</option><option>Preschool (3–5 years)</option><option>Overnight care interest</option></select></label><button disabled={status==="saving"} className="rounded-xl bg-sky-700 px-5 py-3 font-semibold text-white md:col-span-2">{status==="saving"?"Submitting…":"Submit Enrollment Interest"}</button>{status==="done"&&<p className="text-green-700 md:col-span-2">Thank you. Your enrollment request was submitted.</p>}{status==="error"&&<p className="text-red-700 md:col-span-2">We could not submit the form. Please try again or contact the center.</p>}</form></div>}
