import React,{useState} from "react";import {Link} from "react-router-dom";import logo from "../assets/logo.png";import {useAuth} from "../context/AuthContext";
export default function Navbar(){const [open,setOpen]=useState(false);const {user,profile}=useAuth();const links=[["/","Home"],["/about","About"],["/programs","Programs"],["/pricing","Pricing"],["/gallery","Gallery"],["/schedule-tour","Tour"],["/contact","Contact"]];return <header className="sticky top-0 z-50 bg-gradient-to-r from-sky-700 to-indigo-700 text-white shadow"><div className="mx-auto flex max-w-7xl items-center justify-between px-5 py-3"><Link to="/" className="flex items-center gap-3"><img src={logo} alt="Elsie’s Childcare & Learning Center" className="h-12 w-auto"/><span className="hidden font-bold lg:inline">Elsie’s Childcare</span></Link><nav className="hidden items-center gap-5 text-sm font-semibold md:flex">{links.map(([to,l])=><Link key={to} to={to} className="hover:text-sky-100">{l}</Link>)}<Link to={profile?.role==="admin"?"/admin":user?"/parent":"/parent-login"} className="rounded-full bg-white px-4 py-2 text-sky-800">{profile?.role==="admin"?"Admin":user?"Portal":"Parent Login"}</Link></nav><button aria-label="Toggle menu" onClick={()=>setOpen(!open)} className="text-3xl md:hidden">☰</button></div>{open&&<nav className="grid gap-3 bg-white px-6 py-5 font-semibold text-sky-800 md:hidden">{links.map(([to,l])=><Link key={to} to={to} onClick={()=>setOpen(false)}>{l}</Link>)}<Link to={user?"/parent":"/parent-login"} onClick={()=>setOpen(false)}>Parent Portal</Link></nav>}</header>}
